//! Replays `fixtures/physic_scripted.txt` (generated by
//! `Build/physic_fixture_harness/gen_physic.sh` from the original `UnPhysic.cpp`
//! at 58a73d4) through the Rust port with a scripted services mock. The mock
//! reproduces the harness hook draws, log text, and the real `setPhysics` /
//! `FindBase` side effects, so every record's output words and log digest must
//! match bit-for-bit.

use std::cell::RefCell;
use std::collections::BTreeMap;
use std::ffi::c_void;
use std::ptr::null_mut;

use hp2_abi::FVector;
use hp2_abi::engine::generated::{
    AActor, ACarcass, ADecoration, APawn, AZoneInfo, FCheckResult, FRotator,
};
use hp2_engine::physic::{self, Hp2PhysicServices};

const ARG0: usize = 56;
const OUT_WORDS: usize = 51;
const TRACE_ALL_BLOCKING: i32 = 1;
const PHYS_NONE: u8 = 0;
const PHYS_WALKING: u8 = 1;
const FN_NAMES: [&str; 5] = [
    "calc_velocity",
    "mount",
    "step_up",
    "process_hit_wall",
    "process_landed",
];

#[derive(Default)]
struct Scene {
    svc: u64,
    log: String,
    subj: usize,
    subj_class: u32,
    zone: usize,
    pool: [usize; 3],
    pool_class: [u32; 3],
}

thread_local! {
    static SCENE: RefCell<Scene> = RefCell::new(Scene::default());
}

fn with<R>(f: impl FnOnce(&mut Scene) -> R) -> R {
    SCENE.with(|s| f(&mut s.borrow_mut()))
}

fn sm_next(state: &mut u64) -> u64 {
    *state = state.wrapping_add(0x9E37_79B9_7F4A_7C15);
    let mut z = *state;
    z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
    z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
    z ^ (z >> 31)
}

fn unit_of(x: u64) -> f32 {
    (x >> 40) as f32 * (1.0f32 / 16_777_216.0f32)
}

fn svc_unit(s: &mut Scene) -> f32 {
    unit_of(sm_next(&mut s.svc))
}

fn svc_sym(s: &mut Scene) -> f32 {
    2.0f32 * svc_unit(s) - 1.0f32
}

fn bits(f: f32) -> u32 {
    f.to_bits()
}

fn f(w: u32) -> f32 {
    f32::from_bits(w)
}

fn v3(w: &[u32]) -> FVector {
    FVector {
        x: f(w[0]),
        y: f(w[1]),
        z: f(w[2]),
    }
}

fn zero() -> FVector {
    FVector {
        x: 0.0,
        y: 0.0,
        z: 0.0,
    }
}

fn put3(out: &mut [u32], v: FVector) {
    out[0] = bits(v.x);
    out[1] = bits(v.y);
    out[2] = bits(v.z);
}

fn blank_hit(time: f32) -> FCheckResult {
    FCheckResult {
        next: null_mut(),
        actor: null_mut(),
        location: zero(),
        normal: zero(),
        primitive: null_mut(),
        time,
        item: -1,
    }
}

fn fnv1a(bytes: &[u8]) -> u64 {
    let mut h = 1_469_598_103_934_665_603u64;
    for &c in bytes {
        h ^= u64::from(c);
        h = h.wrapping_mul(1_099_511_628_211);
    }
    h
}

fn class_of(s: &Scene, p: usize) -> Option<u32> {
    if p == 0 {
        return None;
    }
    if p == s.subj {
        return Some(s.subj_class);
    }
    s.pool.iter().position(|&q| q == p).map(|k| s.pool_class[k])
}

fn pidx(s: &Scene, p: usize) -> i32 {
    s.pool
        .iter()
        .position(|&q| q == p && p != 0)
        .map_or(-1, |k| k as i32)
}

fn lg(s: &mut Scene, text: String) {
    s.log.push_str(&text);
}

// Class codes: 0 AActor, 1 APawn, 2 APlayerPawn, 3 ADecoration, 4 ACarcass.
fn is_a_impl(s: &Scene, obj: usize, class: i32) -> i32 {
    let Some(code) = class_of(s, obj) else {
        return 0;
    };
    let ok = match class {
        0 => code == 1 || code == 2,
        1 => code == 2,
        2 => code == 3 || code == 4,
        3 => code == 4,
        _ => false,
    };
    i32::from(ok)
}

fn scripted_hit(s: &mut Scene, hit: &mut FCheckResult) {
    let t0 = svc_unit(s);
    let nx = svc_sym(s);
    let ny = svc_sym(s);
    let nz = svc_sym(s);
    let lx = svc_unit(s);
    let ly = svc_unit(s);
    let lz = svc_unit(s);
    let x = sm_next(&mut s.svc);
    let t = if x.is_multiple_of(10) { 1.0 } else { t0 };
    let a = if x.is_multiple_of(4) && t >= 1.0 {
        0
    } else {
        s.pool[((x >> 8) % 3) as usize]
    };
    hit.time = t;
    hit.normal = FVector {
        x: nx,
        y: ny,
        z: nz,
    };
    hit.location = FVector {
        x: lx,
        y: ly,
        z: lz,
    };
    hit.actor = a as *mut c_void;
    let line = format!(
        "hit {:08x} {:08x} {:08x} {:08x} {:08x} {:08x} {:08x} {}\n",
        bits(t),
        bits(nx),
        bits(ny),
        bits(nz),
        bits(lx),
        bits(ly),
        bits(lz),
        pidx(s, a)
    );
    lg(s, line);
}

fn is_probing_impl(s: &mut Scene) -> i32 {
    let ret = (sm_next(&mut s.svc) & 1) as i32;
    lg(s, format!("is_probing {ret}\n"));
    ret
}

fn app_frand_impl(s: &mut Scene) -> f32 {
    let u = svc_unit(s);
    lg(s, format!("app_frand {:08x}\n", bits(u)));
    u
}

unsafe fn cyl_impl(s: &mut Scene, actor: usize) -> FVector {
    let a = unsafe { &*(actor as *const AActor) };
    let v = FVector {
        x: a.collision_radius,
        y: a.collision_radius,
        z: a.collision_height,
    };
    lg(
        s,
        format!(
            "cyl_extent {:08x} {:08x} {:08x}\n",
            bits(v.x),
            bits(v.y),
            bits(v.z)
        ),
    );
    v
}

fn bsp_impl(s: &mut Scene, radius: f32) -> i32 {
    let d = sm_next(&mut s.svc) % 3;
    let code = match d {
        0 => 2,
        1 => 1,
        _ => 0,
    };
    lg(s, format!("bsp_surf {:08x} {code}\n", bits(radius)));
    i32::from(d == 0)
}

fn rot_impl(s: &mut Scene) -> FVector {
    let x = svc_sym(s);
    let y = svc_sym(s);
    let z = svc_sym(s);
    lg(
        s,
        format!(
            "rot_vector {:08x} {:08x} {:08x}\n",
            bits(x),
            bits(y),
            bits(z)
        ),
    );
    FVector { x, y, z }
}

fn move_impl(s: &mut Scene, delta: FVector, rot: FRotator, hit: &mut FCheckResult) -> i32 {
    let ret = i32::from(sm_next(&mut s.svc).is_multiple_of(4));
    lg(
        s,
        format!(
            "move {:08x} {:08x} {:08x} {} {} {} {}\n",
            bits(delta.x),
            bits(delta.y),
            bits(delta.z),
            rot.pitch,
            rot.yaw,
            rot.roll,
            ret
        ),
    );
    if ret == 0 {
        scripted_hit(s, hit);
    }
    ret
}

fn slc_impl(
    s: &mut Scene,
    hit: &mut FCheckResult,
    end: FVector,
    start: FVector,
    trace: i32,
    extent: FVector,
) -> i32 {
    let ret = i32::from(sm_next(&mut s.svc).is_multiple_of(3));
    lg(
        s,
        format!(
            "slc {} {:08x} {:08x} {:08x} {:08x} {:08x} {:08x} {:08x} {:08x} {:08x} {}\n",
            i32::from(trace == TRACE_ALL_BLOCKING),
            bits(end.x),
            bits(end.y),
            bits(end.z),
            bits(start.x),
            bits(start.y),
            bits(start.z),
            bits(extent.x),
            bits(extent.y),
            bits(extent.z),
            ret
        ),
    );
    if ret == 0 {
        scripted_hit(s, hit);
    }
    ret
}

// The harness never assigns `Base`, so it stays NULL and every SetBase path runs.
fn set_base_impl(s: &mut Scene, base: usize) {
    lg(s, format!("set_base {}\n", pidx(s, base)));
}

fn event_mount_impl(s: &mut Scene, dir: FVector) {
    lg(
        s,
        format!(
            "event_mount {:08x} {:08x} {:08x}\n",
            bits(dir.x),
            bits(dir.y),
            bits(dir.z)
        ),
    );
}

fn event_hit_wall_impl(s: &mut Scene, normal: FVector, hit_actor: usize) {
    let p = pidx(s, hit_actor);
    lg(
        s,
        format!(
            "event_hit_wall {:08x} {:08x} {:08x} {}\n",
            bits(normal.x),
            bits(normal.y),
            bits(normal.z),
            p
        ),
    );
}

fn event_landed_impl(s: &mut Scene, normal: FVector) {
    lg(
        s,
        format!(
            "event_landed {:08x} {:08x} {:08x}\n",
            bits(normal.x),
            bits(normal.y),
            bits(normal.z)
        ),
    );
}

fn phys_walking_impl(s: &mut Scene, remaining: f32, iterations: i32) {
    lg(
        s,
        format!("phys_walking {:08x} {iterations}\n", bits(remaining)),
    );
}

// Mirrors `AActor::FindBase` at 58a73d4 (UnPhysic.cpp:95-106).
unsafe fn find_base_impl(s: &mut Scene, actor: usize) {
    let a = actor as *mut AActor;
    let loc = unsafe { (*a).location };
    let mut hit = blank_hit(1.0);
    let extent = unsafe { cyl_impl(s, actor) };
    // `Location + FVector(0,0,-8)` adds +0.0 to x and y (turns -0.0 into +0.0).
    let end = FVector {
        x: loc.x + 0.0,
        y: loc.y + 0.0,
        z: loc.z + -8.0,
    };
    slc_impl(s, &mut hit, end, loc, TRACE_ALL_BLOCKING, extent);
    if !hit.actor.is_null() {
        set_base_impl(s, hit.actor as usize);
    }
}

// Mirrors `AActor::setPhysics` at 58a73d4 (UnPhysic.cpp:107-137).
unsafe fn set_physics_impl(s: &mut Scene, actor: usize, physics: i32, floor: usize) {
    let a = actor as *mut AActor;
    let new = physics as u8;
    if unsafe { (*a).physics } == new {
        return;
    }
    unsafe { (*a).physics = new };
    // process_landed only requests PHYS_None / PHYS_Walking, the walking-branch values.
    if new == PHYS_NONE || new == PHYS_WALKING {
        if floor != 0 {
            set_base_impl(s, floor);
        } else {
            unsafe { find_base_impl(s, actor) };
        }
    }
    if new == PHYS_NONE {
        unsafe {
            (*a).velocity = zero();
            (*a).acceleration = zero();
        }
    }
}

unsafe extern "C" fn m_is_a(obj: *mut c_void, class: i32) -> i32 {
    with(|s| is_a_impl(s, obj as usize, class))
}

unsafe extern "C" fn m_is_probing(_actor: *mut c_void) -> i32 {
    with(is_probing_impl)
}

unsafe extern "C" fn m_app_frand() -> f32 {
    with(app_frand_impl)
}

unsafe extern "C" fn m_cyl(actor: *mut c_void, out: *mut FVector) {
    let v = with(|s| unsafe { cyl_impl(s, actor as usize) });
    unsafe { *out = v };
}

unsafe extern "C" fn m_bsp(_hit: *const FCheckResult, radius: f32) -> i32 {
    with(|s| bsp_impl(s, radius))
}

unsafe extern "C" fn m_rot(_rot: *const FRotator, out: *mut FVector) {
    let v = with(rot_impl);
    unsafe { *out = v };
}

unsafe extern "C" fn m_move(
    _actor: *mut c_void,
    delta: *const FVector,
    rot: *const FRotator,
    hit: *mut FCheckResult,
) -> i32 {
    let (delta, rot) = unsafe { (*delta, *rot) };
    with(|s| move_impl(s, delta, rot, unsafe { &mut *hit }))
}

unsafe extern "C" fn m_slc(
    _actor: *mut c_void,
    hit: *mut FCheckResult,
    end: *const FVector,
    start: *const FVector,
    trace: i32,
    extent: *const FVector,
) -> i32 {
    let (end, start, extent) = unsafe { (*end, *start, *extent) };
    with(|s| slc_impl(s, unsafe { &mut *hit }, end, start, trace, extent))
}

unsafe extern "C" fn m_set_base(_actor: *mut c_void, base: *mut c_void) {
    with(|s| set_base_impl(s, base as usize));
}

unsafe extern "C" fn m_event_mount(_actor: *mut c_void, dir: *const FVector) {
    let dir = unsafe { *dir };
    with(|s| event_mount_impl(s, dir));
}

unsafe extern "C" fn m_event_hit_wall(
    _actor: *mut c_void,
    normal: *const FVector,
    hit_actor: *mut c_void,
) {
    let normal = unsafe { *normal };
    with(|s| event_hit_wall_impl(s, normal, hit_actor as usize));
}

unsafe extern "C" fn m_event_landed(_actor: *mut c_void, normal: *const FVector) {
    let normal = unsafe { *normal };
    with(|s| event_landed_impl(s, normal));
}

unsafe extern "C" fn m_set_physics(actor: *mut c_void, physics: i32, floor: *mut c_void) {
    with(|s| unsafe { set_physics_impl(s, actor as usize, physics, floor as usize) });
}

unsafe extern "C" fn m_phys_walking(actor: *mut c_void, remaining: f32, iterations: i32) {
    let _ = actor;
    with(|s| phys_walking_impl(s, remaining, iterations));
}

static SERVICES: Hp2PhysicServices = Hp2PhysicServices {
    is_a: m_is_a,
    is_probing_hit_wall: m_is_probing,
    app_frand: m_app_frand,
    cylinder_extent: m_cyl,
    bsp_surf_special: m_bsp,
    rotation_vector: m_rot,
    move_actor: m_move,
    single_line_check: m_slc,
    set_base: m_set_base,
    event_mount: m_event_mount,
    event_hit_wall: m_event_hit_wall,
    event_landed: m_event_landed,
    set_physics: m_set_physics,
    phys_walking: m_phys_walking,
};

fn arg_words(name: &str) -> usize {
    match name {
        "calc_velocity" => 9,
        "mount" => 3,
        "step_up" => 9,
        "process_hit_wall" => 4,
        "process_landed" => 6,
        other => panic!("unknown function {other}"),
    }
}

fn pool_or_null(pool: &[usize; 3], idx: u32) -> *mut c_void {
    let i = idx as i32;
    if i < 0 {
        null_mut()
    } else {
        pool[i as usize] as *mut c_void
    }
}

fn run_case(name: &str, seed: u64, w: &[u32]) -> [u32; OUT_WORDS] {
    // Zeroed, 8 KiB-equivalent object memory, matching the harness memset.
    let mut subj = vec![0u64; 1024];
    let mut zone = vec![0u64; 1024];
    let mut pool = [vec![0u64; 1024], vec![0u64; 1024], vec![0u64; 1024]];
    let subj_p = subj.as_mut_ptr() as usize;
    let zone_p = zone.as_mut_ptr() as usize;
    let pool_p = [
        pool[0].as_mut_ptr() as usize,
        pool[1].as_mut_ptr() as usize,
        pool[2].as_mut_ptr() as usize,
    ];

    with(|s| {
        s.svc = seed;
        s.log.clear();
        s.subj = subj_p;
        s.subj_class = w[31];
        s.zone = zone_p;
        s.pool = pool_p;
        s.pool_class = [w[39], w[42], w[45]];
    });

    // SAFETY: each pointer addresses a zeroed buffer of at least the struct size,
    // and the buffers outlive every access below.
    unsafe {
        let z = zone_p as *mut AZoneInfo;
        (*z).zone_gravity = v3(&w[32..35]);
        (*z).zone_velocity = v3(&w[35..38]);
        (*z).set_b_bounce_velocity(w[38] != 0);
        for k in 0..3 {
            let d = pool_p[k] as *mut ADecoration;
            (*d).base.mass = f(w[40 + 3 * k]);
            (*d).set_b_pushable(w[41 + 3 * k] != 0);
        }

        let p = subj_p as *mut APawn;
        (*p).base.location = v3(&w[0..3]);
        (*p).base.rotation = FRotator {
            pitch: w[3] as i32,
            yaw: w[4] as i32,
            roll: w[5] as i32,
        };
        (*p).base.velocity = v3(&w[6..9]);
        (*p).base.acceleration = v3(&w[9..12]);
        (*p).base.physics = w[12] as u8;
        (*p).base.set_b_is_pawn(w[13] != 0);
        (*p).base.set_b_just_teleported(w[14] != 0);
        (*p).set_b_is_walking(w[15] != 0);
        (*p).set_b_from_wall(w[16] != 0);
        (*p).destination = v3(&w[17..20]);
        (*p).accel_rate = f(w[20]);
        (*p).desired_speed = f(w[21]);
        (*p).max_step_height = f(w[22]);
        (*p).max_mount_height = f(w[23]);
        (*p).min_hit_wall = f(w[24]);
        (*p).base.collision_radius = f(w[25]);
        (*p).base.collision_height = f(w[26]);
        (*p).base.mass = f(w[27]);
        (*p).base.buoyancy = f(w[28]);
        (*(subj_p as *mut ADecoration)).num_landings = w[29] as i32;
        (*(subj_p as *mut ACarcass)).set_b_sliding_carcass(w[30] != 0);
        (*p).base.region.zone = zone_p as *mut c_void;
    }

    let mut hit = FCheckResult {
        next: null_mut(),
        actor: pool_or_null(&pool_p, w[55]),
        location: v3(&w[52..55]),
        normal: v3(&w[49..52]),
        primitive: null_mut(),
        time: f(w[48]),
        item: -1,
    };
    let arg = &w[ARG0..];
    let subj_apawn = subj_p as *mut APawn;
    let ret = unsafe {
        match name {
            "calc_velocity" => {
                physic::calc_velocity(
                    subj_apawn,
                    &SERVICES,
                    v3(&arg[0..3]),
                    f(arg[3]),
                    f(arg[4]),
                    f(arg[5]),
                    arg[6] as i32,
                    arg[7] as i32,
                    arg[8] as i32,
                );
                0
            }
            "mount" => u32::from(physic::mount(
                subj_apawn,
                &SERVICES,
                v3(&arg[0..3]),
                &mut hit,
            )),
            "step_up" => {
                physic::step_up(
                    subj_apawn,
                    &SERVICES,
                    v3(&arg[0..3]),
                    v3(&arg[3..6]),
                    v3(&arg[6..9]),
                    &mut hit,
                );
                0
            }
            "process_hit_wall" => {
                physic::process_hit_wall(
                    subj_p as *mut AActor,
                    &SERVICES,
                    v3(&arg[0..3]),
                    pool_p[arg[3] as usize] as *mut c_void,
                );
                0
            }
            "process_landed" => {
                physic::process_landed(
                    subj_p as *mut AActor,
                    &SERVICES,
                    v3(&arg[0..3]),
                    pool_or_null(&pool_p, arg[3]),
                    f(arg[4]),
                    arg[5] as i32,
                );
                0
            }
            other => panic!("unknown function {other}"),
        }
    };

    let mut out = [0u32; OUT_WORDS];
    // SAFETY: same buffers as above, still alive.
    unsafe {
        let p = subj_p as *const APawn;
        let a = &(*p).base;
        put3(&mut out[0..3], a.location);
        out[3] = a.rotation.pitch as u32;
        out[4] = a.rotation.yaw as u32;
        out[5] = a.rotation.roll as u32;
        put3(&mut out[6..9], a.velocity);
        put3(&mut out[9..12], a.acceleration);
        out[12] = u32::from(a.physics);
        out[13] = u32::from(a.b_is_pawn());
        out[14] = u32::from(a.b_just_teleported());
        out[15] = u32::from((*p).b_is_walking());
        out[16] = u32::from((*p).b_from_wall());
        put3(&mut out[17..20], (*p).destination);
        out[20] = bits((*p).accel_rate);
        out[21] = bits((*p).desired_speed);
        out[22] = bits((*p).max_step_height);
        out[23] = bits((*p).max_mount_height);
        out[24] = bits((*p).min_hit_wall);
        out[25] = bits(a.collision_radius);
        out[26] = bits(a.collision_height);
        out[27] = bits(a.mass);
        out[28] = bits(a.buoyancy);
        out[29] = (*(subj_p as *const ADecoration)).num_landings as u32;
        out[30] = u32::from((*(subj_p as *const ACarcass)).b_sliding_carcass());
        out[31] = with(|s| s.subj_class);

        let z = zone_p as *const AZoneInfo;
        put3(&mut out[32..35], (*z).zone_gravity);
        put3(&mut out[35..38], (*z).zone_velocity);
        out[38] = u32::from((*z).b_bounce_velocity());
    }
    out[39] = bits(hit.time);
    put3(&mut out[40..43], hit.normal);
    put3(&mut out[43..46], hit.location);
    out[46] = with(|s| pidx(s, hit.actor as usize)) as u32;
    out[47] = ret;
    let digest = with(|s| fnv1a(s.log.as_bytes()));
    let len = with(|s| s.log.len());
    out[48] = (digest >> 32) as u32;
    out[49] = digest as u32;
    out[50] = len as u32;
    // Keep the backing storage alive until every read above has finished.
    drop((subj, zone, pool));
    out
}

#[test]
fn physic_scripted_matches_original() {
    assert!(std::mem::size_of::<APawn>() <= 8192);
    assert!(std::mem::size_of::<AZoneInfo>() <= 8192);

    let text = include_str!("fixtures/physic_scripted.txt");
    let mut per_fn: BTreeMap<&str, usize> = BTreeMap::new();
    let mut total = 0usize;
    let mut no_hit = 0usize;
    let mut null_actor = 0usize;

    for (rec, line) in text.lines().enumerate() {
        let toks: Vec<&str> = line.split_whitespace().collect();
        let sep = toks
            .iter()
            .position(|t| *t == "|")
            .unwrap_or_else(|| panic!("record {rec}: missing separator"));
        let name = toks[0];
        let seed = u64::from_str_radix(toks[1], 16).expect("seed");
        let input: Vec<u32> = toks[2..sep]
            .iter()
            .map(|t| u32::from_str_radix(t, 16).expect("input word"))
            .collect();
        let expect: Vec<u32> = toks[sep + 1..]
            .iter()
            .map(|t| u32::from_str_radix(t, 16).expect("output word"))
            .collect();
        assert_eq!(
            input.len(),
            ARG0 + arg_words(name),
            "record {rec} ({name}): input width"
        );
        assert_eq!(
            expect.len(),
            OUT_WORDS,
            "record {rec} ({name}): output width"
        );

        let got = run_case(name, seed, &input);
        if let Some(i) = (0..OUT_WORDS).find(|&i| got[i] != expect[i]) {
            panic!(
                "record {rec} {name} seed {seed:016x}: word {i} expected {:08x} got {:08x}",
                expect[i], got[i]
            );
        }

        *per_fn.entry(name).or_default() += 1;
        total += 1;
        if expect[39] == 0x3f80_0000 {
            no_hit += 1;
        }
        if expect[46] == u32::MAX {
            null_actor += 1;
        }
    }

    assert_eq!(total, 6000);
    for name in FN_NAMES {
        assert_eq!(per_fn.get(name).copied(), Some(1200), "{name} case count");
    }
    assert!(no_hit > 0, "no-hit (Time == 1) coverage");
    assert!(null_actor > 0, "NULL hit-actor coverage");
}
